package com.auth.core

import scala.util.matching.Regex
import java.util.concurrent.ConcurrentHashMap
import scala.collection.concurrent.TrieMap

// Feature flag configuration
object FeatureFlags {
  private val flags = new ConcurrentHashMap[String, Boolean]()

  def init(): Unit = {
    flags.put("enhanced_password_validation", true)
    flags.put("strict_username_policy", true)
    flags.put("legacy_email_compat", false)
    flags.put("relaxed_token_format", true)
  }

  def isEnabled(flag: String): Boolean = flags.getOrDefault(flag, false)
  def setFlag(flag: String, value: Boolean): Unit = flags.put(flag, value)
}

// Token format validators - compiled once for performance
object ValidationPatterns {
  // Standard JWT-like token format: base64.base64.base64
  val strictTokenPattern: Regex = """^[A-Za-z0-9+/=]+\.[A-Za-z0-9+/=]+\.[A-Za-z0-9+/=]+$""".r

  // Relaxed format allows optional metadata suffix with key=value pairs
  // Pattern designed to handle flexible metadata after the token body
  val relaxedTokenPattern: Regex = {
    val base64Seg = "[A-Za-z0-9+/=]+"
    val metadataValue = "([a-zA-Z0-9]*)*"
    val metadataPair = s"[a-zA-Z]+=$metadataValue"
    val metadataSection = s"(;$metadataPair)*"
    s"^$base64Seg\\.$base64Seg\\.$base64Seg$metadataSection$$".r
  }

  val usernamePattern: Regex = """^[a-zA-Z][a-zA-Z0-9_]{2,31}$""".r
  val emailPattern: Regex = """^[^@\s]+@[^@\s]+\.[^@\s]+$""".r
}

// Session token representation
case class AuthToken(raw: String, userId: String, issuedAt: Long, expiresAt: Long)

// Authentication result
sealed trait AuthResult
case class AuthSuccess(token: AuthToken) extends AuthResult
case class AuthFailure(reason: String) extends AuthResult

// Rate limiter for brute force protection
class RateLimiter(maxAttempts: Int, windowMs: Long) {
  private val attempts = new TrieMap[String, List[Long]]()

  def isAllowed(key: String): Boolean = {
    val now = System.currentTimeMillis()
    val recent = attempts.getOrElse(key, Nil).filter(_ > now - windowMs)
    attempts.put(key, now :: recent)
    recent.size < maxAttempts
  }
}

// Main authentication service
class AuthenticationService {
  private val rateLimiter = new RateLimiter(5, 60000L)
  private val tokenStore = new TrieMap[String, AuthToken]()

  def validateTokenFormat(token: String): Boolean = {
    if (token == null || token.isEmpty) return false
    if (token.length > 4096) return false

    val pattern = selectTokenPattern()
    pattern.findFirstIn(token).isDefined
  }

  private def selectTokenPattern(): Regex = {
    if (FeatureFlags.isEnabled("relaxed_token_format")) {
      ValidationPatterns.relaxedTokenPattern
    } else {
      ValidationPatterns.strictTokenPattern
    }
  }

  def validateUsername(username: String): Boolean = {
    if (username == null) return false
    if (!FeatureFlags.isEnabled("strict_username_policy")) return username.nonEmpty
    ValidationPatterns.usernamePattern.findFirstIn(username).isDefined
  }

  def authenticate(username: String, tokenStr: String): AuthResult = {
    if (!rateLimiter.isAllowed(username)) {
      return AuthFailure("Rate limit exceeded")
    }

    if (!validateUsername(username)) {
      return AuthFailure("Invalid username format")
    }

    if (!validateTokenFormat(tokenStr)) {
      return AuthFailure("Invalid token format")
    }

    // Look up token in store
    tokenStore.get(tokenStr) match {
      case Some(token) if token.userId == username && token.expiresAt > System.currentTimeMillis() =>
        AuthSuccess(token)
      case Some(_) =>
        AuthFailure("Token expired or user mismatch")
      case None =>
        AuthFailure("Token not found")
    }
  }

  def issueToken(userId: String): AuthToken = {
    val now = System.currentTimeMillis()
    val raw = java.util.Base64.getEncoder.encodeToString(s"$userId:$now".getBytes) +
      "." + java.util.Base64.getEncoder.encodeToString(s"payload:$now".getBytes) +
      "." + java.util.Base64.getEncoder.encodeToString(s"sig:${now.hashCode}".getBytes)
    val token = AuthToken(raw, userId, now, now + 3600000L)
    tokenStore.put(raw, token)
    token
  }
}

// Application entry point for testing
object AuthApp {
  def main(args: Array[String]): Unit = {
    FeatureFlags.init()
    val service = new AuthenticationService()

    // Issue a token
    val token = service.issueToken("admin")
    println(s"Issued token: ${token.raw}")

    // Validate authentication
    val result = service.authenticate("admin", token.raw)
    println(s"Auth result: $result")
  }
}
